//! Hostile-input corpus contract and typed-rejection tests (T-0183).
//!
//! Every file in `fixtures/hostile/` is generated by `pdfxi_testkit::hostile`
//! and exercised through the parser entry points reachable from this crate:
//! `pdfxi_core::Document::from_bytes`, `page_count`, `page_content`, and the
//! five panic-free `pdfxi_testkit::fuzz` entry points. The core library is a
//! normal dependency of the testkit, so these are the real parsers, not mocks.
//!
//! Fixtures whose declared category is `tolerated` have no typed-error path at
//! the probed entry point (the construct is a data-shape hazard, not a grammar
//! error). Those are asserted by byte shape plus the no-panic/no-hang contract,
//! and the reason is recorded in each manifest row's `intent`.

use std::fs;
use std::panic::{self, AssertUnwindSafe};

use pdfxi_core::{Document, Error};
use pdfxi_testkit::fixtures::{FIXTURE_COUNT, all as all_valid};
use pdfxi_testkit::fuzz::{fuzz_content, fuzz_crypto, fuzz_filters, fuzz_forms, fuzz_parser};
use pdfxi_testkit::hash::sha256_hex;
use pdfxi_testkit::hostile::{
    HOSTILE_CORPUS_SIZE_BUDGET, HOSTILE_COUNT, HOSTILE_FILE_MAX_BYTES, HostileBuilder,
    HostileFixture, Probe, all, committed_manifest, emit_manifest, manifest_shape, parse_manifest,
};

type Target = (&'static str, fn(&[u8]) -> pdfxi_testkit::fuzz::FuzzOutcome);

const TARGETS: &[Target] = &[
    ("parser", fuzz_parser),
    ("filters", fuzz_filters),
    ("content", fuzz_content),
    ("forms", fuzz_forms),
    ("crypto", fuzz_crypto),
];

fn builder_for(name: &str) -> HostileBuilder {
    all()
        .into_iter()
        .find(|fixture| fixture.name == name)
        .unwrap_or_else(|| panic!("no hostile builder named {name}"))
}

fn bytes_for(fixture: &HostileBuilder) -> Vec<u8> {
    (fixture.build)()
}

fn on_disk_bytes(fixture: &HostileFixture) -> Vec<u8> {
    let path = pdfxi_testkit::hostile::corpus_dir().join(&fixture.name);
    fs::read(&path).unwrap_or_else(|error| panic!("read {}: {error}", path.display()))
}

/// Return the typed error produced by the fixture's declared probe.
fn probe_error(bytes: &[u8], probe: Probe) -> Option<Error> {
    let document = match Document::from_bytes(bytes.to_vec()) {
        Ok(document) => document,
        Err(error) => return (probe == Probe::Open).then_some(error),
    };
    match probe {
        Probe::Open => None,
        Probe::Pages => document.page_count().err(),
        Probe::Content => document.page_content(0).err(),
    }
}

fn run_all_probes(bytes: &[u8]) {
    let _ = Document::from_bytes(bytes.to_vec());
    if let Ok(document) = Document::from_bytes(bytes.to_vec()) {
        let _ = document.page_count();
        let _ = document.page_content(0);
    }
}

#[test]
fn hostile_corpus_has_the_declared_count() {
    assert_eq!(all().len(), HOSTILE_COUNT);
    assert_eq!(committed_manifest().len(), HOSTILE_COUNT);
    assert!(
        HOSTILE_COUNT >= 12,
        "the batch must add at least 12 fixtures"
    );
}

#[test]
fn valid_fifty_fixture_corpus_is_unchanged() {
    // The hostile corpus is additive. The valid M1 corpus keeps its 50-fixture
    // count and `corpus_contains_fifty_fixtures` contract untouched.
    assert_eq!(FIXTURE_COUNT, 50);
    assert_eq!(all_valid().len(), FIXTURE_COUNT);
    let valid = all_valid();
    let valid_names: Vec<&str> = valid.iter().map(|f| f.file_name.as_str()).collect();
    for fixture in all() {
        assert!(
            !valid_names.contains(&fixture.name),
            "{} collides with a valid fixture",
            fixture.name
        );
    }
}

#[test]
fn hostile_manifest_matches_generated_descriptors() {
    let on_disk = committed_manifest();
    let generated = parse_manifest(&emit_manifest(&all()));
    assert!(!on_disk.is_empty(), "hostile manifest is missing");
    assert_eq!(on_disk, generated);
}

#[test]
fn hostile_manifest_hashes_are_lowercase_and_match_files() {
    for entry in committed_manifest() {
        assert_eq!(entry.sha256.len(), 64, "hash length for {}", entry.name);
        assert!(
            entry
                .sha256
                .bytes()
                .all(|byte| byte.is_ascii_hexdigit() && !byte.is_ascii_uppercase()),
            "hash must be lowercase hex for {}",
            entry.name
        );
        assert_eq!(
            sha256_hex(&on_disk_bytes(&entry)),
            entry.sha256,
            "SHA-256 mismatch for {}",
            entry.name
        );
    }
}

#[test]
fn hostile_manifest_categories_and_probes_are_known() {
    for entry in committed_manifest() {
        assert!(
            pdfxi_testkit::hostile::Category::parse(&entry.category).is_some(),
            "{} has an unknown category {:?}",
            entry.name,
            entry.category
        );
        assert!(
            Probe::parse(&entry.probe).is_some(),
            "{} has an unknown probe {:?}",
            entry.name,
            entry.probe
        );
        assert!(!entry.intent.is_empty(), "{} has no intent", entry.name);
    }
}

#[test]
fn hostile_shape_markers_are_valid_hex_and_present_on_disk() {
    for entry in committed_manifest() {
        let shape = manifest_shape(&entry)
            .unwrap_or_else(|| panic!("{} has a non-hex shape field", entry.name));
        assert!(!shape.is_empty(), "{} has an empty shape", entry.name);
        let bytes = on_disk_bytes(&entry);
        assert!(
            bytes.windows(shape.len()).any(|window| window == shape),
            "{} is missing its expected structure marker",
            entry.name
        );
    }
}

#[test]
fn every_hostile_file_is_within_the_size_budget() {
    let mut total = 0usize;
    for fixture in all() {
        let bytes = bytes_for(&fixture);
        assert!(
            bytes.len() < HOSTILE_FILE_MAX_BYTES,
            "{} is {} bytes",
            fixture.name,
            bytes.len()
        );
        // Also comfortably below the 8 KiB ceiling in the task statement.
        assert!(bytes.len() < 8 * 1024, "{} exceeds 8 KiB", fixture.name);
        total += bytes.len();
    }
    assert!(
        total < HOSTILE_CORPUS_SIZE_BUDGET,
        "hostile corpus is {total} bytes"
    );
}

#[test]
fn generators_reproduce_committed_hostile_bytes() {
    for fixture in all() {
        let entry = committed_manifest()
            .into_iter()
            .find(|entry| entry.name == fixture.name)
            .unwrap_or_else(|| panic!("{} missing from manifest", fixture.name));
        assert_eq!(
            on_disk_bytes(&entry),
            bytes_for(&fixture),
            "{} is stale; regenerate the hostile corpus",
            fixture.name
        );
        assert_eq!(
            bytes_for(&fixture),
            bytes_for(&fixture),
            "{} is not byte-stable",
            fixture.name
        );
    }
}

#[test]
fn hostile_names_are_unique() {
    let mut names: Vec<&str> = all().iter().map(|fixture| fixture.name).collect();
    names.sort_unstable();
    let before = names.len();
    names.dedup();
    assert_eq!(names.len(), before);
}

#[test]
fn every_hostile_fixture_runs_all_probes_without_panicking() {
    for fixture in all() {
        let bytes = bytes_for(&fixture);
        let outcome = panic::catch_unwind(AssertUnwindSafe(|| run_all_probes(&bytes)));
        assert!(
            outcome.is_ok(),
            "{} panicked in a parser probe",
            fixture.name
        );
    }
}

#[test]
fn every_hostile_fixture_runs_every_fuzz_target_without_panicking() {
    for fixture in all() {
        let bytes = bytes_for(&fixture);
        for (name, target) in TARGETS {
            let outcome = panic::catch_unwind(AssertUnwindSafe(|| target(&bytes)));
            let outcome = outcome.unwrap_or_else(|_| {
                panic!("{} panicked in the {name} fuzz entry point", fixture.name)
            });
            assert_eq!(outcome.input_len, bytes.len(), "{name}/{}", fixture.name);
        }
    }
}

#[test]
fn fuzz_entry_points_reach_real_code_on_hostile_input() {
    // Every target must exercise at least one success or structured rejection;
    // zero counters would mean the entry point silently stopped reading input.
    for (name, target) in TARGETS {
        let mut cases = 0usize;
        for fixture in all() {
            let outcome = target(&bytes_for(&fixture));
            cases += outcome.accepted + outcome.rejected;
        }
        assert!(cases > 0, "{name} fuzz target reached no parser code");
    }
}

#[test]
fn declared_probes_return_the_expected_typed_error() {
    let mut checked = 0usize;
    for fixture in all() {
        if fixture.category == pdfxi_testkit::hostile::Category::Tolerated {
            continue;
        }
        let bytes = bytes_for(&fixture);
        let observed = panic::catch_unwind(AssertUnwindSafe(|| probe_error(&bytes, fixture.probe)))
            .unwrap_or_else(|_| panic!("{} panicked during its declared probe", fixture.name));
        let error = observed.unwrap_or_else(|| {
            panic!(
                "{} declared {:?} at {:?} but the probe succeeded",
                fixture.name, fixture.category, fixture.probe
            )
        });
        assert!(
            fixture.category.matches(&error),
            "{} expected {:?} but got {error:?}",
            fixture.name,
            fixture.category
        );
        checked += 1;
    }
    assert!(
        checked >= 10,
        "expected at least 10 typed-rejection fixtures, got {checked}"
    );
}

#[test]
fn tolerated_fixtures_are_accepted_but_keep_their_shape() {
    let mut checked = 0usize;
    for fixture in all() {
        if fixture.category != pdfxi_testkit::hostile::Category::Tolerated {
            continue;
        }
        let bytes = bytes_for(&fixture);
        assert!(
            Document::from_bytes(bytes.clone()).is_ok(),
            "{} should parse structurally",
            fixture.name
        );
        assert!(
            bytes
                .windows(fixture.shape.len())
                .any(|window| window == fixture.shape),
            "{} lost its cycle marker",
            fixture.name
        );
        checked += 1;
    }
    assert!(checked >= 3, "expected at least three tolerated fixtures");
}

#[test]
fn xref_hostile_fixtures_are_typed_rejections() {
    for name in ["xref-truncated.pdf", "xref-past-eof.pdf"] {
        let fixture = builder_for(name);
        let error = probe_error(&bytes_for(&fixture), fixture.probe)
            .unwrap_or_else(|| panic!("{name} was accepted"));
        assert!(fixture.category.matches(&error), "{name} got {error:?}");
    }
}

#[test]
fn object_stream_and_page_tree_hostile_fixtures_are_typed_rejections() {
    for name in [
        "objstm-bad-n.pdf",
        "objstm-bad-first.pdf",
        "page-tree-missing-kids.pdf",
        "catalog-missing-pages.pdf",
        "trailer-missing-root.pdf",
    ] {
        let fixture = builder_for(name);
        let error = probe_error(&bytes_for(&fixture), fixture.probe)
            .unwrap_or_else(|| panic!("{name} was accepted"));
        assert!(fixture.category.matches(&error), "{name} got {error:?}");
    }
}

#[test]
fn stream_and_nesting_hostile_fixtures_are_typed_rejections() {
    for name in [
        "stream-absurd-length.pdf",
        "nested-filter-parms.pdf",
        "deep-arrays.pdf",
        "deep-dicts.pdf",
    ] {
        let fixture = builder_for(name);
        let error = probe_error(&bytes_for(&fixture), fixture.probe)
            .unwrap_or_else(|| panic!("{name} was accepted"));
        assert!(fixture.category.matches(&error), "{name} got {error:?}");
    }
}

#[test]
fn hostile_corpus_covers_every_requested_attack_family() {
    let names: Vec<&str> = all().iter().map(|fixture| fixture.name).collect();
    for required in [
        "xref-truncated.pdf",
        "xref-past-eof.pdf",
        "objstm-bad-n.pdf",
        "objstm-bad-first.pdf",
        "cyclic-page-tree.pdf",
        "page-tree-missing-kids.pdf",
        "catalog-missing-pages.pdf",
        "stream-absurd-length.pdf",
        "nested-filter-parms.pdf",
        "deep-arrays.pdf",
        "deep-dicts.pdf",
        "utf16-lone-surrogate.pdf",
        "annot-recursive-p.pdf",
        "form-field-cyclic-kids.pdf",
        "struct-tree-parent-cycle.pdf",
    ] {
        assert!(
            names.contains(&required),
            "missing attack family {required}"
        );
    }
}
